'use strict';
const $=s=>document.querySelector(s),log=$('#log'),canvas=$('#brain'),ctx=canvas.getContext('2d');
let state={active:false,muted:false},mic=null,audioCtx=null,analyser=null,vadRAF=0,recorder=null,chunks=[],speechFrames=0,silenceSince=0,recordStarted=0,voiceBusy=false,cooldownUntil=0;
let neural={nodes:[],fibers:[],activity:[]},topology={graph:new Map(),cores:[],activity:new Map(),pathEdges:new Set(),pathNodes:new Map(),canonical:new Set(),routes:[]},screenNodes=[],rot={x:-.08,y:.18},drag=null,selectedId=null;
const CORE_VALUES=new Set(['core','kernel','supervisor','spine','registry','orchestrator','brain_core','neural_core','system_core']);
const CORE_ID_RE=/(?:^|[._:\/-])(core|kernel|supervisor|spine)(?:$|[._:\/-])/i;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function add(w,t,k='eira'){let p=document.createElement('p');p.className='msg '+k;p.innerHTML=`<span class="who">${esc(w)}</span>${esc(t)}`;log.appendChild(p);log.scrollTop=log.scrollHeight}
async function req(u,o={}){let r=await fetch(u,{cache:'no-store',...o}),j={};try{j=await r.json()}catch{}if(!r.ok)throw Error(j.error||`${r.status} ${r.statusText}`);return j}
function updateState(){let label=!state.active?'INACTIVE':state.muted?'MUTED':voiceBusy?'TRANSCRIBING':'LISTENING';$('#activePill').textContent=label;$('#activateBtn').textContent=state.active?'DEACTIVATE EIRA':'ACTIVATE EIRA';$('#muteBtn').textContent=state.muted?'UNMUTE':'MUTE';document.body.classList.toggle('listening',state.active&&!state.muted);document.body.classList.toggle('muted',state.muted)}
function renderBridges(b){let box=$('#runtime');box.innerHTML='';Object.entries(b||{}).forEach(([k,v])=>{let d=document.createElement('div');d.className='r '+(v.healthy?'ok':'bad');d.innerHTML=`<b>${v.healthy?'●':'○'} ${esc(k.replaceAll('_',' ').toUpperCase())}</b><span>${esc(v.detail||'')}</span>`;box.appendChild(d)})}
async function health(){try{let r=await fetch('/health',{cache:'no-store'}),j=await r.json();state=j.runtime||state;updateState();renderBridges(j.bridges);$('#statusDot').classList.toggle('ok',!!j.ok);$('#headline').textContent=j.ok?`SERVER QUALIFIED · :${j.port||8782}`:'SERVER PARTIALLY READY'}catch{$('#headline').textContent='SERVER UNREACHABLE'}}
async function submitText(text,source='text'){let clean=String(text||'').trim();if(!clean)return null;add(source==='voice'?'You · voice':'You',clean,'me');let j=await req('/v1/text',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:clean,source})}),r=j.result||j;let answer=r.text||r.reply||r.response||JSON.stringify(r);add('Eira',answer);return r}
function bestMime(){for(let m of ['audio/mp4;codecs=mp4a.40.2','audio/mp4','audio/webm;codecs=opus','audio/webm'])if(window.MediaRecorder?.isTypeSupported?.(m))return m;return ''}
async function acquireMic(){if(mic&&mic.active)return mic;if(!window.isSecureContext)throw Error('Microphone requires HTTPS on iPhone Safari');if(!navigator.mediaDevices?.getUserMedia)throw Error('Browser microphone API unavailable');if(!window.MediaRecorder)throw Error('Browser MediaRecorder API unavailable');mic=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true},video:false});audioCtx=new (window.AudioContext||window.webkitAudioContext)();await audioCtx.resume();let src=audioCtx.createMediaStreamSource(mic);analyser=audioCtx.createAnalyser();analyser.fftSize=1024;analyser.smoothingTimeConstant=.32;src.connect(analyser);return mic}
function applyMute(){if(mic)mic.getAudioTracks().forEach(t=>t.enabled=!state.muted)}
function stopRecorder(){if(recorder&&recorder.state==='recording')recorder.stop()}
let pcmNode=null,pcmFrames=[];

function packPCM16(frames,inputRate){
  let total=frames.reduce((n,a)=>n+a.length,0),src=new Float32Array(total),o=0;
  for(let a of frames){src.set(a,o);o+=a.length}
  let ratio=inputRate/16000,outLen=Math.max(1,Math.floor(src.length/ratio)),buf=new ArrayBuffer(outLen*2),dv=new DataView(buf);
  for(let i=0;i<outLen;i++){
    let start=Math.floor(i*ratio),end=Math.max(start+1,Math.floor((i+1)*ratio)),sum=0,n=0;
    for(let j=start;j<end&&j<src.length;j++){sum+=src[j];n++}
    let s=Math.max(-1,Math.min(1,n?sum/n:0));
    dv.setInt16(i*2,s<0?s*32768:s*32767,true)
  }
  return buf
}

function beginUtterance(){
  if(!mic||voiceBusy||state.muted||pcmNode)return;
  pcmFrames=[];
  let src=audioCtx.createMediaStreamSource(mic);
  pcmNode=audioCtx.createScriptProcessor(4096,1,1);
  pcmNode.onaudioprocess=e=>pcmFrames.push(new Float32Array(e.inputBuffer.getChannelData(0)));
  src.connect(pcmNode);pcmNode.connect(audioCtx.destination);
  recorder={state:'recording',stop:async()=>{
    if(!pcmNode)return;
    let node=pcmNode;pcmNode=null;
    try{node.disconnect()}catch{}
    document.body.classList.remove('hearing');
    let frames=pcmFrames;pcmFrames=[];
    if(!frames.length)return;
    voiceBusy=true;document.body.classList.add('transcribing');updateState();
    try{
      let body=packPCM16(frames,audioCtx.sampleRate);
      let j=await req('/v1/listen?sample_rate=16000&channels=1&sample_width=2',{
        method:'POST',
        headers:{'Content-Type':'application/octet-stream'},
        body
      });
      let transcript=String(j.utterance||j.text||'').trim();
      let r=j.result||j;
      let answer=r.text||r.reply||r.response;
      if(transcript)add('You · voice',transcript,'me');
      if(answer)add('Eira',answer);
    }catch(e){add('Voice path',e.message,'err')}
    finally{
      voiceBusy=false;document.body.classList.remove('transcribing');
      cooldownUntil=performance.now()+850;updateState()
    }
  }};
  recordStarted=performance.now();silenceSince=0;document.body.classList.add('hearing')
}
function vadLoop(){if(!state.active||!analyser){vadRAF=0;return}let a=new Uint8Array(analyser.fftSize);analyser.getByteTimeDomainData(a);let sum=0;for(let v of a){let x=(v-128)/128;sum+=x*x}let rms=Math.sqrt(sum/a.length),now=performance.now(),speaking=rms>.028;if(state.muted||voiceBusy||now<cooldownUntil){speechFrames=0}else if(recorder?.state==='recording'){if(speaking)silenceSince=0;else if(!silenceSince)silenceSince=now;if((silenceSince&&now-silenceSince>900&&now-recordStarted>350)||now-recordStarted>12000)stopRecorder()}else{speechFrames=speaking?speechFrames+1:0;if(speechFrames>=3){speechFrames=0;beginUtterance()}}vadRAF=requestAnimationFrame(vadLoop)}
function startVAD(){cancelAnimationFrame(vadRAF);vadRAF=requestAnimationFrame(vadLoop)}
async function stopMic(){cancelAnimationFrame(vadRAF);vadRAF=0;stopRecorder();if(mic){mic.getTracks().forEach(t=>t.stop());mic=null}if(audioCtx){await audioCtx.close().catch(()=>{});audioCtx=null}analyser=null;document.body.classList.remove('hearing','transcribing')}
$('#activateBtn').onclick=async()=>{try{let next=!state.active;if(next){await acquireMic();state.active=true;state.muted=false;applyMute();updateState();startVAD()}else{await stopMic();state.active=false;state.muted=false;updateState()}}catch(e){add('Activation error',e.message,'err')}};
$('#muteBtn').onclick=async()=>{try{if(!state.active)throw Error('Activate Eira first');state.muted=!state.muted;applyMute();if(state.muted)stopRecorder();updateState()}catch(e){add('Mute error',e.message,'err')}};
$('#form').onsubmit=async e=>{e.preventDefault();let i=$('#input'),text=i.value.trim();if(!text)return;i.value='';try{await submitText(text,'text')}catch(x){add('Conversation bridge',x.message,'err')}};
$('#inventBtn').onclick=()=>{location.href='/inventions/'};
$('#arBtn').onclick=async()=>{try{let j=await req('/api/inventions/usdz'),a=(j.models||[])[0];if(!a||!a.href)throw Error('No verified brain USDZ available');location.href=a.href}catch(e){add('Apple AR',e.message,'err')}};
function dataOf(x){return x&&x.data!==undefined?x.data:x}function nodesOf(x){let d=dataOf(x);return Array.isArray(d)?d:d?.nodes||d?.neurons||[]}function fibersOf(x){let d=dataOf(x);return Array.isArray(d)?d:d?.fibers||d?.edges||[]}function explicitId(n){for(let k of ['id','node_id','name','path'])if(n?.[k]!=null&&String(n[k]).trim())return String(n[k]).trim();return null}function id(n,i){return explicitId(n)||`n${i}`}function ends(f){let a=f?.source??f?.from??f?.a??f?.source_id,b=f?.target??f?.to??f?.b??f?.target_id;return[a==null?null:String(a).trim(),b==null?null:String(b).trim()]}function score(a){for(let k of ['activity','score','strength','level','weight','value']){let v=Number(a?.[k]);if(Number.isFinite(v))return Math.max(0,Math.min(1,v))}return 1}
function explicitCore(n){let nid=explicitId(n)||'';if(CORE_ID_RE.test(nid))return true;for(let k of ['role','type','kind','class','category','authority']){let v=n?.[k];if(typeof v==='string'&&CORE_VALUES.has(v.trim().toLowerCase()))return true;if(Array.isArray(v)&&v.some(x=>CORE_VALUES.has(String(x).trim().toLowerCase())))return true}return false}
function activityTargets(a){let out=[],push=v=>{if(typeof v==='string'&&v.trim())out.push(v.trim());else if(v&&typeof v==='object'){let x=explicitId(v);if(x)out.push(x)}};let direct=explicitId(a);if(direct)out.push(direct);for(let k of ['target','target_id','node','node_id'])push(a?.[k]);for(let k of ['targets','node_ids','participants','contributors','active_nodes'])if(Array.isArray(a?.[k]))a[k].forEach(push);return [...new Set(out)]}
function pathTo(target,g,starts){let q=[...starts],prev=new Map(),seen=new Set(starts);while(q.length){let cur=q.shift();if(cur===target){let p=[cur];while(prev.has(cur)){cur=prev.get(cur);p.push(cur)}return p.reverse()}for(let nx of g.get(cur)||[])if(!seen.has(nx)){seen.add(nx);prev.set(nx,cur);q.push(nx)}}return[]}
function rebuild(){let canonical=new Set(neural.nodes.map((n,i)=>id(n,i))),g=new Map();canonical.forEach(n=>g.set(n,[]));for(let f of neural.fibers){let[a,b]=ends(f);if(a&&b&&canonical.has(a)&&canonical.has(b)){g.get(a).push(b);g.get(b).push(a)}}let cores=[];neural.nodes.forEach((n,i)=>{if(explicitCore(n))cores.push(id(n,i))});let activity=new Map(),pathEdges=new Set(),pathNodes=new Map(),routes=[];for(let a of neural.activity){let s=score(a);for(let target of activityTargets(a)){if(!canonical.has(target))continue;activity.set(target,Math.max(activity.get(target)||0,s));if(!cores.length)continue;let p=pathTo(target,g,cores);if(!p.length)continue;routes.push({target,strength:s,path:p,event:a});p.forEach((n,i)=>{pathNodes.set(n,Math.max(pathNodes.get(n)||0,s*(.35+.65*i/Math.max(1,p.length-1))));if(i)pathEdges.add([p[i-1],n].sort().join('\0'))})}}topology={graph:g,cores,activity,pathEdges,pathNodes,canonical,routes};$('#neurons').textContent=neural.nodes.length;$('#fibers').textContent=neural.fibers.length;$('#brainState').textContent=!neural.nodes.length?'WAITING FOR CANONICAL INVENTORY':!cores.length?'CANONICAL CORE MISSING · ROUTING BLOCKED':`CANONICAL NETWORK ONLINE · ${routes.length} LIVE ROUTE${routes.length===1?'':'S'}`}
function posFor(n,i,N){let x=Number(n.x),y=Number(n.y),z=Number(n.z);if([x,y,z].every(Number.isFinite))return{x,y,z};let hemi=i%2?-1:1,t=(i+0.5)/Math.max(1,N),phi=Math.acos(1-2*t),theta=Math.PI*(1+Math.sqrt(5))*i;let r=.72+.23*((i*37)%17)/16;return{x:hemi*Math.abs(r*Math.sin(phi)*Math.cos(theta)),y:r*Math.cos(phi),z:r*Math.sin(phi)*Math.sin(theta)}}
function project(p,w,h){let cy=Math.cos(rot.y),sy=Math.sin(rot.y),cx=Math.cos(rot.x),sx=Math.sin(rot.x),x=p.x*cy-p.z*sy,z=p.x*sy+p.z*cy,y=p.y*cx-z*sx;z=p.y*sx+z*cx;let scale=Math.min(w,h)*.39*(1/(1.7-.35*z));return{x:w/2+x*scale,y:h/2+y*scale,z,scale}}
function electronPhase(routeIndex,particleIndex,t){return(t*(.42+.07*(routeIndex%5))+particleIndex*.23+routeIndex*.11)%1}
function bezier(A,B,u,bend){let mx=(A.x+B.x)/2,my=(A.y+B.y)/2-14*bend,om=1-u;return{x:om*om*A.x+2*om*u*mx+u*u*B.x,y:om*om*A.y+2*om*u*my+u*u*B.y}}
function draw(){let rect=canvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr)}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);let map=new Map(),N=neural.nodes.length;screenNodes=[];neural.nodes.forEach((n,i)=>{let p=project(posFor(n,i,N),w,h);map.set(id(n,i),p);screenNodes.push({id:id(n,i),n,x:p.x,y:p.y,z:p.z})});for(let f of neural.fibers){let[a,b]=ends(f),A=map.get(a),B=map.get(b);if(!A||!B)continue;let active=topology.pathEdges.has([a,b].sort().join('\0')),bend=((String(a).length+String(b).length)%3)-1;ctx.beginPath();ctx.moveTo(A.x,A.y);ctx.quadraticCurveTo((A.x+B.x)/2,(A.y+B.y)/2-14*bend,B.x,B.y);ctx.strokeStyle=active?'rgba(255,209,102,.82)':'rgba(85,239,255,.18)';ctx.lineWidth=active?1.9:.55;ctx.stroke()}let t=performance.now()/1000;topology.routes.forEach((route,ri)=>{let p=route.path;if(p.length<2)return;let particles=Math.max(2,Math.min(8,Math.ceil(2+route.strength*6)));for(let pi=0;pi<particles;pi++){let phase=electronPhase(ri,pi,t),segments=p.length-1,scaled=phase*segments,si=Math.min(segments-1,Math.floor(scaled)),u=scaled-si,A=map.get(p[si]),B=map.get(p[si+1]);if(!A||!B)continue;let bend=((String(p[si]).length+String(p[si+1]).length)%3)-1,q=bezier(A,B,u,bend);ctx.beginPath();ctx.arc(q.x,q.y,1.4+2.0*route.strength,0,Math.PI*2);ctx.fillStyle='rgba(255,238,160,.98)';ctx.shadowBlur=18+12*route.strength;ctx.shadowColor='#ffd166';ctx.fill();ctx.shadowBlur=0}});for(let s of screenNodes.sort((a,b)=>a.z-b.z)){let strength=Math.max(topology.activity.get(s.id)||0,topology.pathNodes.get(s.id)||0),core=topology.cores.includes(s.id),selected=s.id===selectedId,r=core?3.8:1.25+(s.z+1)*.45;if(strength)r+=3.5*strength;if(selected)r+=3;ctx.beginPath();ctx.arc(s.x,s.y,r,0,Math.PI*2);ctx.fillStyle=strength?`rgba(255,${180+Math.floor(70*strength)},110,.97)`:core?'rgba(255,209,102,.92)':'rgba(100,235,255,.72)';ctx.shadowBlur=strength?24:selected?22:core?16:7;ctx.shadowColor=strength?'#ffd166':selected?'#b98cff':core?'#ff9f43':'#55efff';ctx.fill();ctx.shadowBlur=0;if(selected){ctx.beginPath();ctx.arc(s.x,s.y,r+7+2*Math.sin(t*5),0,Math.PI*2);ctx.strokeStyle='rgba(185,140,255,.9)';ctx.lineWidth=1.5;ctx.stroke()}}for(let [target,strength] of topology.activity){let p=map.get(target);if(!p)continue;ctx.beginPath();ctx.arc(p.x,p.y,7+8*strength+2*Math.sin(t*5),0,Math.PI*2);ctx.strokeStyle=`rgba(255,209,102,${.35+.55*strength})`;ctx.lineWidth=1.5;ctx.stroke()}requestAnimationFrame(draw)}
function showNodeRecord(best){let l=$('#nodeLabel');if(!best){l.classList.remove('show');return}selectedId=best.id;let direct=topology.activity.get(best.id)||0,path=topology.pathNodes.get(best.id)||0,role=best.n.role||best.n.type||best.n.kind||best.n.class||'canonical neuron';l.innerHTML=`<b>${esc(best.id)}</b>${esc(role)} · direct ${direct.toFixed(2)} · routed ${path.toFixed(2)}`;l.style.left=Math.max(8,Math.min(canvas.clientWidth-300,best.x+12))+'px';l.style.top=Math.max(45,best.y-10)+'px';l.classList.add('show')}
function showNode(x,y){let best=null,dist=18;for(let s of screenNodes){let d=Math.hypot(s.x-x,s.y-y);if(d<dist){best=s;dist=d}}showNodeRecord(best)}
function findCanonicalNode(query){let q=String(query||'').trim().toLowerCase();if(!q)return null;let exact=neural.nodes.map((n,i)=>({id:id(n,i),n})).find(x=>x.id.toLowerCase()===q);let hit=exact||neural.nodes.map((n,i)=>({id:id(n,i),n})).find(x=>JSON.stringify(x.n).toLowerCase().includes(q)||x.id.toLowerCase().includes(q));if(!hit)return null;let screen=screenNodes.find(s=>s.id===hit.id);if(screen)showNodeRecord(screen);return hit}
$('#findForm').onsubmit=e=>{e.preventDefault();let q=$('#nodeFind').value,hit=findCanonicalNode(q);if(!hit){selectedId=null;$('#nodeLabel').classList.remove('show');add('Neuron finder',`No canonical neuron matches “${q}”.`,'err')}else add('Neuron finder',`Showing ${hit.id}.`,'me')};
canvas.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.abs(dx)+Math.abs(dy)>2)drag.moved=true;rot.y+=dx*.006;rot.x+=dy*.006;drag.x=e.clientX;drag.y=e.clientY;$('#nodeLabel').classList.remove('show')});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){let r=canvas.getBoundingClientRect();showNode(e.clientX-r.left,e.clientY-r.top)}drag=null});
async function refreshNeural(){try{let [o,f,a]=await Promise.all([req('/api/neural/overview'),req('/api/neural/fibers'),req('/api/neural/activity')]);let nd=[],cursor='';do{let u='/api/neural/nodes'+(cursor?'?cursor='+encodeURIComponent(cursor):''),page=await req(u);nd.push(...(Array.isArray(page?.neurons)?page.neurons:[]));cursor=page?.next_cursor||''}while(cursor);neural.nodes=nd;neural.fibers=fibersOf(f);let ad=dataOf(a);neural.activity=Array.isArray(ad)?ad:ad?.activity||ad?.events||ad?.nodes||[];rebuild()}catch(e){$('#brainState').textContent='NEURAL DATA UNAVAILABLE'}}
window.addEventListener('pagehide',()=>stopMic());health();refreshNeural();setInterval(health,5000);setInterval(refreshNeural,1200);requestAnimationFrame(draw);

:root{--rail:190px;--right:250px;--cyan:#55efff;--teal:#28e6c8;--gold:#ffd166;--amber:#ff9f43;--violet:#b98cff;--mag:#ff65c5;--glass:rgba(3,15,27,.72);--sphere:min(78vh,64vw)}
html,body{width:100%;height:100%;min-height:100%;margin:0;background:radial-gradient(circle at 50% 46%,#082641 0,#020812 38%,#000205 76%)!important;overflow:hidden!important}
body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.88;background:radial-gradient(circle at 50% 46%,rgba(85,239,255,.14),transparent 27%),radial-gradient(circle at 43% 46%,rgba(255,101,197,.08),transparent 20%),radial-gradient(circle at 57% 50%,rgba(255,209,102,.08),transparent 22%),linear-gradient(rgba(85,239,255,.024) 1px,transparent 1px),linear-gradient(90deg,rgba(85,239,255,.024) 1px,transparent 1px)!important;background-size:auto,auto,auto,36px 36px,36px 36px!important}
body:after{content:"";position:fixed;inset:-25%;pointer-events:none;background:conic-gradient(from 0deg at 50% 47%,transparent 0 8%,rgba(85,239,255,.08) 12%,transparent 18% 34%,rgba(185,140,255,.07) 39%,transparent 45% 61%,rgba(255,209,102,.06) 67%,transparent 73% 88%,rgba(255,101,197,.06) 93%,transparent 100%);filter:blur(72px);animation:referenceAurora 26s linear infinite}@keyframes referenceAurora{to{transform:rotate(360deg)}}
.shell{width:100vw!important;height:100dvh;margin:0!important;padding:max(12px,env(safe-area-inset-top)) 16px max(12px,env(safe-area-inset-bottom))!important;position:relative!important;overflow:hidden!important}
.top{position:fixed;z-index:30;left:24px;right:24px;top:max(14px,env(safe-area-inset-top));height:74px;margin:0!important;pointer-events:none}.brand{pointer-events:auto;max-width:300px}.brand h1{margin:0;font-size:clamp(35px,4.2vw,58px)!important;font-weight:300;line-height:.9;letter-spacing:.15em!important;text-shadow:0 0 18px rgba(85,239,255,.85),0 0 45px rgba(85,239,255,.24)!important}.brand small{display:block;margin-top:8px;max-width:280px;font-size:9px!important;line-height:1.45;letter-spacing:.18em!important;color:#86cbe3!important;text-transform:uppercase}.top>.actions{position:fixed;right:18px;top:max(20px,env(safe-area-inset-top));pointer-events:auto;display:flex;gap:8px}.top>.actions .btn{font-size:9px;padding:9px 11px;opacity:.94}
.grid{display:block!important;width:100%;height:100%}
.brainCard{position:fixed!important;z-index:3!important;left:50%!important;top:49%!important;right:auto!important;bottom:auto!important;width:var(--sphere)!important;height:var(--sphere)!important;min-height:0!important;aspect-ratio:1/1;transform:translate(-50%,-50%);background:transparent!important;border:0!important;box-shadow:none!important;overflow:visible!important;isolation:isolate}
